const D = { energy:.55, density:.5, scale:1, speed:1, alpha:.72, hue:190, x:.5, y:.45, style:'vitreous', act:'drift', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const lrp=(a,b,t)=>a+(b-a)*t;
const md=(a,n)=>((a%n)+n)%n;
const frc=v=>v-Math.floor(v);
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};

const W=width, Hh=height, u=Math.min(W,Hh);
const H=md(P.hue,360);
const st=P.style, act=P.act||'drift';
const isGra=st==='graphic', isMic=st==='microscope', isPho=st==='phosphene';
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const en=clp(P.energy,0,1), dn=clp(P.density,0,1), al=clp(P.alpha,0,1);
const sp=P.speed, sc=clp(P.scale,0.25,2.4);
const cx=P.x*W, cy=P.y*Hh;
let sacA=1, sinkR=1;
if(act==='saccade'){ sacA=2.1; sinkR=0.6; }
else if(act==='settle'){ sacA=0; sinkR=1.5; }

// ---- pre-blurred debris sprites: out-of-focus is the whole point, so blur once at build ----
if(!S.sp){
  const SZ=64; S.sp=[];
  const g0=createGraphics(SZ,SZ); g0.pixelDensity(1); g0.colorMode(HSB,360,100,100,100); g0.clear(); g0.noStroke();
  for(let r=24;r>0;r-=1.5){ g0.fill(0,0,100,2.0); g0.circle(32,32,r*2); }        // soft interior haze
  g0.noFill(); g0.stroke(0,0,100,72); g0.strokeWeight(3.4); g0.circle(32,32,40); // refractive rim
  g0.filter(BLUR,4); S.sp.push(g0);
  const g1=createGraphics(SZ,SZ); g1.pixelDensity(1); g1.colorMode(HSB,360,100,100,100); g1.clear();
  g1.noFill(); g1.stroke(0,0,100,88); g1.strokeWeight(5); g1.circle(32,32,44);   // Weiss ring
  g1.filter(BLUR,3); S.sp.push(g1);
}

// ---- gaze: two incommensurate saccade trains (7.3s and 11.9s — never in step with the 8s gate) ----
const sacc=(per,salt)=>{
  const idx=Math.floor(K.t/per+fr(salt)), ph=frc(K.t/per+fr(salt));
  const tx=(fr(idx*3+salt+1)-0.5), ty=(fr(idx*3+salt+2)-0.5);
  const px=(fr((idx-1)*3+salt+1)-0.5), py=(fr((idx-1)*3+salt+2)-0.5);
  // the vitreous keeps going after the eye stops: overshoot, then a damped settle
  const e=1-Math.exp(-ph*9);
  const ring=Math.exp(-ph*2.6)*Math.sin(ph*13.5)*0.42;
  return [lrp(px,tx,e)+(tx-px)*ring, lrp(py,ty,e)+(ty-py)*ring];
};
const s1=sacc(7.3/Math.max(0.15,sp),1), s2=sacc(11.9/Math.max(0.15,sp),9);
const lurch=u*0.16*sacA*(0.4+0.9*en)*sc;
const gx=(s1[0]*0.62+s2[0]*0.38)*lurch;
const gy=(s1[1]*0.62+s2[1]*0.38)*lurch + K.t*0.0083*sp*sinkR*u; // unbounded sink ramp; each floater wraps on its own via md()

// ---- vitreous haze: the faint base the debris floats in ----
if(!isGra&&!isMic){
  noStroke();
  for(let b=0;b<3;b++){
    const bb=0.5+0.5*Math.sin(K.t*(0.037+b*0.029)*sp+fr(b+60)*6.283);
    fill(md(H+b*8,360), isPho?42:20, isPho?26:34, clp((isPho?5:4)*al*(0.4+0.8*en)*(0.5+0.5*bb),0,7));
    ellipse(cx+Math.sin(K.t*0.041*sp+b*2.1)*u*0.10, cy+Math.cos(K.t*0.033*sp+b)*u*0.07,
            u*lrp(1.5,0.8,b/2)*sc, u*lrp(1.1,0.6,b/2)*sc);
  }
}
// ---- microscope graticule: the clinical frame this style lives in ----
if(isMic){
  stroke(md(H+150,360),46,74,16*al); strokeWeight(Math.max(0.4,u*0.0008));
  for(let i=-6;i<=6;i++){ line(cx+i*u*0.075,cy-u*0.42,cx+i*u*0.075,cy+u*0.42); line(cx-u*0.42,cy+i*u*0.075,cx+u*0.42,cy+i*u*0.075); }
  stroke(md(H+150,360),52,96,44*al); strokeWeight(Math.max(0.5,u*0.0014));
  for(let i=-5;i<=5;i++){ const tx=cx+i*u*0.075; line(tx,cy+u*0.40,tx,cy+u*0.40-(i%5===0?u*0.022:u*0.010)); }
  noFill(); stroke(md(H+150,360),40,88,28*al); circle(cx,cy,u*0.86);
}

// ---- the debris: chained collagen strands, squiggles and Weiss rings ----
const nF=Math.max(2,Math.round(lrp(5,22,dn)));
imageMode(CENTER);
for(let i=0;i<nF;i++){
  const j=i*37;
  const kind=fr(j+1);                                     // <0.20 ring, <0.62 bead chain, else squiggle thread
  const depth=fr(j+2);                                    // parallax: deep debris lags and blurs more
  const bx=cx+(fr(j+3)-0.5)*u*1.5*sc + gx*lrp(0.55,1.25,depth);
  const by=cy+(fr(j+4)-0.5)*u*1.1*sc + gy*lrp(0.55,1.25,depth);
  const wy=md(by+u*0.35, Hh+u*0.7)-u*0.35;                // sink wraps back to the top
  const wob=Math.sin(K.t*(0.19+fr(j+5)*0.37)*sp+fr(j+6)*6.283)*u*0.018*(0.4+en)*sc;
  const ang=fr(j+7)*6.283+K.t*(0.017+fr(j+8)*0.041)*sp;
  const sz=u*lrp(0.016,0.052,fr(j+9))*sc*(0.5+0.9*en)*lrp(0.7,1.25,depth);
  const aa=clp((isGra?62:isMic?58:isPho?40:46)*al*lrp(0.55,1,depth)*(0.35+0.9*en),0,88);
  if(aa<1.5) continue;
  push(); translate(bx+wob,wy); rotate(ang);
  if(isPho) blendMode(ADD);
  const beads=kind<0.20?1:Math.max(2,Math.round(lrp(3,8,fr(j+10))*(0.4+0.8*dn)));
  for(let b=0;b<beads;b++){
    const f=beads>1?b/(beads-1):0.5;
    // beads strung along a bent path — collagen fibrils clump, they are never a neat line
    const px2=(f-0.5)*sz*lrp(3.5,7.5,fr(j+11));
    const py2=Math.sin(f*Math.PI*lrp(0.8,2.4,fr(j+12))+fr(j+13)*6.283)*sz*1.5
             + Math.sin(K.t*(0.4+fr(j+14)*0.9)*sp+f*3.1)*sz*0.28*(0.3+en);
    const br=sz*lrp(0.55,1.25,fr(j*2+b+20));
    if(isGra){
      noStroke(); fill(md(H+6,360), 8, 96, aa*lrp(0.7,1,f));
      ellipse(px2,py2,br*2*(kind<0.20?1.6:1),br*1.5);
      noFill(); stroke(md(H+6,360),12,100,aa*0.5); strokeWeight(Math.max(0.5,br*0.16));
      if(b>0) line(px2,py2,(( (b-1)/(Math.max(1,beads-1)) )-0.5)*sz*lrp(3.5,7.5,fr(j+11)),py2*0.6);
    } else if(isMic){
      noFill(); stroke(md(H+150,360),lrp(30,4,f),100,aa); strokeWeight(Math.max(0.5,br*0.22));
      circle(px2,py2,br*1.9);
      stroke(md(H+150,360),56,88,aa*0.5); strokeWeight(Math.max(0.4,br*0.10));
      circle(px2,py2,br*0.8);
    } else {
      tint(md(H+(isPho?fr(j*2+b+30)*90:8),360), isPho?lrp(64,22,f):lrp(26,6,f), isPho?100:lrp(72,100,f), aa*lrp(0.72,1,f));
      image(S.sp[kind<0.20?1:0], px2, py2, br*2*(kind<0.20?2.4:1.9), br*2*(kind<0.20?2.0:1.9));
    }
  }
  if(isPho) blendMode(BLEND);
  pop();
}
imageMode(CORNER);

